import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"5. 研究设计与评估方法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/tmpa-architecture-paper-a0.5/part-02.md","filePath":"zh/publications/tmpa-architecture-paper-a0.5/part-02.md","lastUpdated":1786085052000}'),r={name:"zh/publications/tmpa-architecture-paper-a0.5/part-02.md"};function i(n,t,s,l,p,c){return a(),o("div",null,[...t[0]||(t[0]=[d(`<p>一个生命周期 Profile 包含：</p><ul><li>有限状态集合 <code>S</code>；</li><li>初始状态 <code>s0</code>；</li><li>终止状态集合 <code>F</code>；</li><li>动作集合 <code>A</code>；</li><li>迁移关系 <code>T ⊆ S × A × S</code>；</li><li>授权函数 <code>Auth(role, action, object)</code>；</li><li>验证函数 <code>Valid(object, transition)</code>。</li></ul><p>只有满足以下条件，迁移才会被接受：</p><ol><li>来源状态与当前权威状态一致；</li><li><code>T</code> 定义了该迁移；</li><li>发起角色获得授权；</li><li>所需引用与前置条件已经满足；</li><li>迁移证据通过 Schema 与完整性验证。</li></ol><p>非法或未经授权的迁移不会改变权威生命周期状态。尝试本身必须通过拒绝、ISSUE、告警或 Profile 规定的等价记录保持可观察，而不能被静默丢弃或修复。</p><h2 id="_4-5-文本消息、单写者流与异步并行" tabindex="-1">4.5 文本消息、单写者流与异步并行 <a class="header-anchor" href="#_4-5-文本消息、单写者流与异步并行" aria-label="Permalink to &quot;4.5 文本消息、单写者流与异步并行&quot;">​</a></h2><p>TMPA 的写入平面把稳定工作载体、单写者对象、局部串行与异步组合结合起来。</p><p>对于每个受治理任务或工作项 <code>t</code>，面向任务的 Profile 定义一个稳定主载体 <code>c_t</code>。主载体建立工作 ID 与最低治理上下文。接受、执行报告、复核、决策、更正和恢复记录都是引用 <code>c_t</code> 的独立对象，而不是任务的更多可变副本。因此，“一任务一载体”指一个稳定主引用点，而不是所有参与者共同编辑的一份文档。</p><p>令 <code>A</code> 为责任写者集合。每个已发布对象恰好有一个写者，每个写者 <code>a ∈ A</code> 发布一条可独立归属的串行流：</p><p><code>S_a = ⟨o_{a,1}, o_{a,2}, ..., o_{a,n}⟩</code></p><p><code>S_a</code> 内部序列是该写者的权威局部顺序。每个对象具有正整数序号，<code>(stream_id, sequence)</code> 标识其在该写者责任历史中的位置。创建时间可以提供信息，但不是流顺序的权威依据。</p><p>在观测时刻 <code>τ</code>，可用候选集合可能包含各条流的不同前缀：</p><p><code>O_τ = ⋃_{a ∈ A} prefix(S_a, k_a(τ))</code></p><p>函数 <code>k_a(τ)</code> 不必同步推进。一个参与者可以先发布任务而另一个仍离线；报告可以先于独立复核出现；多个写者可以并发推进。这就是多条串行流形成异步并行的方式。TMPA 不要求所有参与者共享时钟、同时在线，或共同写入一条全局 Event Log。</p><p>流内前驱关系提供局部顺序。显式引用和 Profile 定义的生命周期依赖提供跨流因果边。如果两个对象既没有流内关系，也没有 Profile 定义的跨流依赖，它们保持并发且不可比较。</p><p>单写者对象与分离的责任流消除了主要的<strong>语义共享写冲突</strong>：多个 Agent 不再争抢修改一份权威记录。但它们不会消除所有存储层争用、文件系统竞态或基础设施故障；Profile 仍必须定义原子发布、重复处理和恢复行为。</p><p>写入模型可以概括为：</p><blockquote><p><strong>一项任务有一个主载体。每个已发布对象由一个写者拥有。每个写者内部保持串行。多条流异步推进，形成并行协作。</strong></p></blockquote><h2 id="_4-6-读端聚合与治理重建" tabindex="-1">4.6 读端聚合与治理重建 <a class="header-anchor" href="#_4-6-读端聚合与治理重建" aria-label="Permalink to &quot;4.6 读端聚合与治理重建&quot;">​</a></h2><p>TMPA 的读取平面包含两个概念上分离的阶段：<strong>来源聚合</strong>与<strong>治理重建</strong>。</p><p>令 <code>O_τ</code> 为观测时刻 <code>τ</code> 可见的有限来源候选集合。保留来源的聚合器 <code>A</code> 发现来源工件，保留来源身份和字节，解析候选封装，对 ID 与引用建立索引，并应用 Reader 所需的确定性规范化：</p><p><code>C_τ = A(O_τ)</code></p><p>聚合阶段不决定哪项声明为真，不静默修复冲突，不虚构缺失证据，也不把到达顺序转换为治理顺序。其目的，是构建治理 Reader 当前可用的完整规范候选集合 <code>C_τ</code>，同时保留每个来源候选的来源信息。</p><p>令 <code>P</code> 为固定规则 Profile，其中包含 Schema、类型规则、角色分配、生命周期规则、关系语义、规范化规则、冲突策略和输出规范化规则。治理 Reader 计算：</p><p><code>R_P(C_τ) = (G_τ, I_τ)</code></p><p>其中，<code>G_τ</code> 是规范重建得到的偏序流程与治理图，<code>I_τ</code> 是规范问题集合。<code>G_τ</code> 表示工作流进度、责任、生命周期、复核、批准、拒绝、恢复与审计关系，同时保留局部流顺序、显式跨流依赖以及不可比较对象之间的并发。它不是权威总时间线。</p><p>为简化表述，后文可用 <code>R_P(O)</code> 表示组合管线 <code>R_P(A(O))</code>。主要确定性要求是排列不变性。对同一规范候选集合的任意排列 <code>π</code>：</p><p><code>R_P(A(π(O))) = R_P(A(O))</code></p><p>相等性适用于 <code>G</code> 与 <code>I</code> 的规范序列化结果，而不是偶然的内存顺序或诊断格式。延迟到达会改变当前可用集合，并可能合法地把视图从 partial 改为 authoritative 或 disputed；但同一集合的不同枚举顺序不得改变结果。</p><p><strong>确定性命题。</strong> 令 <code>O</code> 为有限来源多重集合，<code>P</code> 为固定 Profile。假定：(1) 来源规范化是来源身份与被覆盖字节的纯函数；(2) 重复分类、验证、权限检查、生命周期检查与问题 ID 都是规范对象值和 <code>P</code> 的函数；(3) 图边仅由流内序号和 Profile 声明关系导出；(4) 图与问题序列化使用已发布的确定性排序及 Tie-break 规则。则组合运算 <code>R_P(A(O))</code> 对来源枚举顺序不变。</p><p><strong>证明概要。</strong> 因为索引与重复分类依赖规范来源值而非发现位置，所以聚合会把 <code>O</code> 的任意枚举映射为同一规范索引候选多重集合。逐对象验证与顺序无关。集合级检查——重复 ID、流缺口、缺失引用、禁止环、权限冲突和生命周期冲突——都在同一规范集合与关系上计算。因此，每次排列得到的已接受节点集合与有向边集合相同。规范问题 ID 与确定性排序产生相同 <code>I</code>；规范图序列化以及仅用于表示不可比较节点的稳定 Tie-break 产生相同序列化 <code>G</code>。所以每种排列都产生字节等价的规范输出。该论证只在所述 Profile 契约下证明排列不变性；它不证明语义真实性、Profile 正确性、对受损信任根的抵抗，或不同证据集合之间的相等。更强保证仍需机械化证明和可执行语料库。</p><p>重建主体或子图首先获得三值治理判断，再映射为运行视图：</p><ul><li><strong>authoritative：</strong> 通常对应 <code>valid</code>，所需证据有效，且没有影响结论的未解决完整性、权限、生命周期、顺序或必需引用问题；</li><li><strong>partial：</strong> 对应因所需证据缺失、流或依赖不完整而形成的 <code>undetermined</code>；</li><li><strong>disputed：</strong> 对应多个有效但不兼容的治理声明尚未解决时形成的 <code>undetermined</code>；</li><li><strong>quarantined：</strong> Profile 定义的完整性、身份、重复 ID 或禁止环条件使相关证据被排除在权威重建之外；它不自动证明底层业务声明为假。</li></ul><p>认证是正交的保证标签。对象或视图可以在 TMPA Core 下结构性 authoritative，但在更强身份 Profile 下仍未认证；此时不得把它表述为具有认证完整性。</p><p>TMPA 要求<strong>冲突保留</strong>：相互矛盾但有效的对象必须保持在表示中，直至出现新的授权解决对象。它还要求<strong>扩展时证据保留</strong>：增加候选证据不会擦除先前来源证据。TMPA 不假定治理状态在任意集合扩展下单调，因为新加入的有效证据可能合法地把先前 authoritative 的视图改变为 partial、disputed 或 quarantined。</p><p>因此，读端重建不是完整架构本身，而是把持久文本消息和异步串行流转换为一致流程与治理结果的阶段。系统可以为互换或展示生成确定性拓扑序列化，但该序列化不会在不可比较节点之间增加治理顺序。C11 运行化来源聚合与重建确定性；C03、C04、C09、C10 与 C12 测试身份、顺序、依赖、环和冲突保留行为。完整重建性质的机械化证明仍属于未来工作。</p><h2 id="_4-7-完整性与签名证据" tabindex="-1">4.7 完整性与签名证据 <a class="header-anchor" href="#_4-7-完整性与签名证据" aria-label="Permalink to &quot;4.7 完整性与签名证据&quot;">​</a></h2><p>TMPA 区分三种常被混淆的性质：</p><ol><li><strong>归属（Attribution）：</strong> 对象声明创建者和责任角色。</li><li><strong>完整性（Integrity）：</strong> 已发布对象被修改时能够检测。</li><li><strong>认证完整性（Authenticated integrity）：</strong> 对象通过密码学方式绑定到已验证身份或密钥。</li></ol><p>TMPA Core 要求归属与完整性证据。只有应用可信身份、签名和密钥管理 Profile 时，部署才能声称具备认证完整性。</p><p>完整性记录标识：</p><ul><li>规范化 Profile；</li><li>Hash 算法；</li><li>内容摘要；</li><li>Profile 要求时的前驱或引用摘要；</li><li>可选签名算法；</li><li>可选密钥 ID；</li><li>可选签名值。</li></ul><p>角色标签不是密码学签名。没有可信身份绑定的摘要可以检测修改，却不能证明谁创建了对象。有效签名在部署的信任模型下证明来源与完整性，但不证明被签名内容在语义上为真。</p><h2 id="_4-8-概念关系、历史谱系与运行栈" tabindex="-1">4.8 概念关系、历史谱系与运行栈 <a class="header-anchor" href="#_4-8-概念关系、历史谱系与运行栈" aria-label="Permalink to &quot;4.8 概念关系、历史谱系与运行栈&quot;">​</a></h2><p>第 1 节定位图区分历史谱系、当前概念关系和端到端运行。本节固定软件边界：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA 架构</span></span>
<span class="line"><span>        ↓ 实现已定义子集的可复用 FCoP 协议 Profile</span></span>
<span class="line"><span>FCoP</span></span>
<span class="line"><span>        ↓ 被下列系统作为协调与治理基础设施采用</span></span>
<span class="line"><span>CodeFlowMu 与其他下游应用</span></span></code></pre></div><p>FCoP 具有独立规范与实现；CodeFlowMu 是下游采用者。二者都不定义更广泛的 TMPA 架构。</p><p>FCoP 运行栈为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用层                 CodeFlowMu / Cursor / Claude Desktop</span></span>
<span class="line"><span>Host 适配层            fcop-mcp / fcop-cli / Host Bridges</span></span>
<span class="line"><span>FCoP 协议层            协作 / 报告 / 复核 /</span></span>
<span class="line"><span>                       能力治理 / 事件 / 审计</span></span>
<span class="line"><span>参考实现               fcop Python Library</span></span>
<span class="line"><span>执行基底               LLM API / MCP 工具 / 文件系统 /</span></span>
<span class="line"><span>                       进程管理器 / 操作系统</span></span></code></pre></div><p>TMPA 不是该栈中的 Runtime 组件。<code>fcop</code> Package 是 FCoP 的参考实现；CodeFlowMu 是范围更广的应用环境。该分离同时保持历史准确性与一致性边界。</p><hr><h1 id="_5-研究设计与评估方法" tabindex="-1">5. 研究设计与评估方法 <a class="header-anchor" href="#_5-研究设计与评估方法" aria-label="Permalink to &quot;5. 研究设计与评估方法&quot;">​</a></h1><p>本文是一项设计科学架构研究。研究构造治理工件，分析其内部性质，通过参考 Profile 实例化该工件，并评估边界明确的工程证据。本文不是因果试验、性能基准或生态采用声明。</p><h2 id="_5-1-设计科学过程" tabindex="-1">5.1 设计科学过程 <a class="header-anchor" href="#_5-1-设计科学过程" aria-label="Permalink to &quot;5.1 设计科学过程&quot;">​</a></h2><p>研究由五个相互衔接的阶段组成：</p><table tabindex="0"><thead><tr><th>阶段</th><th>研究操作</th><th>输出与研究问题</th></tr></thead><tbody><tr><td>问题诊断</td><td>分析聊天、日志、工作流与小典谱系中的协调缺口</td><td>DR1–DR8；RQ1</td></tr><tr><td>工件构造</td><td>定义对象、流、权限、生命周期与重建规则</td><td>TMPA 架构；RQ2</td></tr><tr><td>分析性评估</td><td>检查不变量、反例与保证边界</td><td>结构可靠性；RQ1–RQ2</td></tr><tr><td>参考实例化</td><td>把 FCoP 工件和操作映射到 TMPA 概念</td><td>实现可行性；RQ3</td></tr><tr><td>案例观察与一致性基线</td><td>检查 CodeFlowMu、小典路径、Fixture 与锁定测试结果</td><td>有界演示；RQ3</td></tr></tbody></table><p>分析单元分别是治理对象、受治理工作项、重建视图和部署 Profile。该划分避免把产品功能、单个文件与架构层声明视为可互换证据。</p><h2 id="_5-2-证据与声明协议" tabindex="-1">5.2 证据与声明协议 <a class="header-anchor" href="#_5-2-证据与声明协议" aria-label="Permalink to &quot;5.2 证据与声明协议&quot;">​</a></h2><p>证据被分类为 <strong>specified</strong>、<strong>implemented</strong>、<strong>demonstrated</strong> 或 <strong>independently adopted</strong>。一致性证据还记录固定来源修订、证据 Hash、执行前置条件、预期与实际输出，以及 PASS、PARTIAL、NOT RUN 或 FAIL 四种产品裁决之一。Fixture Oracle 匹配与产品执行分开报告。</p><p>该协议限制三类常见推断错误：历史工件不会被追溯性包装为专门设计的一致性测试；前置条件失败不会被转换为通过或产品失败；作者生成案例不会被视为独立采用。该过程支持结构与实现可行性声明，但不支持关于生产率、成本、可靠性或组织结果的因果声明。</p><h2 id="_5-3-fcop-作为参考实例化" tabindex="-1">5.3 FCoP 作为参考实例化 <a class="header-anchor" href="#_5-3-fcop-作为参考实例化" aria-label="Permalink to &quot;5.3 FCoP 作为参考实例化&quot;">​</a></h2><p>FCoP（File-based Coordination Protocol，文件型协调协议）是本文用于检验 TMPA 语义能否在普通、项目可见文件系统中实现的参考 Profile。概念关系为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA 架构 → 可复用 FCoP 协议 Profile → CodeFlowMu 与其他下游应用</span></span></code></pre></div><p>FCoP 不等同于 TMPA。它通过命名文本工件、生命周期目录、面向追加的迁移证据、Schema、Runtime 工具与适配器，实现 TMPA 的文件型子集 [7]–[12]。CodeFlowMu 是使用 FCoP 概念构建持久多角色开发环境的下游应用 [13]。</p><table tabindex="0"><thead><tr><th>FCoP 元素</th><th>TMPA 解释</th></tr></thead><tbody><tr><td>工件 ID 或文件名 Stem</td><td>稳定且对传输可见的对象身份</td></tr><tr><td><code>sender</code> 与 <code>recipient</code></td><td>声明写者与预期责任转移</td></tr><tr><td>生命周期路径与 <code>transitions</code></td><td>Profile 定义的状态与迁移证据</td></tr><tr><td><code>references</code>、<code>ref_task</code>、<code>subject_ref</code></td><td>类型化因果或治理链接</td></tr><tr><td><code>REVIEW</code> 与批准证据</td><td>独立裁决与决策</td></tr><tr><td><code>supersedes</code></td><td>不破坏性重写的更正</td></tr><tr><td>Archive/History</td><td>保留的终态证据</td></tr></tbody></table><p>在该 Profile 下，一项任务有一个稳定且对传输可见的载体；报告、复核、ISSUE、批准与更正保持为独立工件。写者彼此独立发布，Reader 检查当前可用来源集合。已发布的 Runtime Specification、Schema、Package、Adapter、Governance Middleware、ADR 和文档证明实现与分发路径，而不是广泛采用 [8]–[16]。</p><h2 id="_5-4-案例与语料库程序" tabindex="-1">5.4 案例与语料库程序 <a class="header-anchor" href="#_5-4-案例与语料库程序" aria-label="Permalink to &quot;5.4 案例与语料库程序&quot;">​</a></h2><p>历史谱系为小典 AI → FCoP → CodeFlowMu。小典暴露了跨模型 Session 保留任务接受、执行、复核、拒绝与审计证据的需求 [25]。FCoP 抽取可复用的协调与复核骨架；CodeFlowMu 提供规模更大的持久工作应用。</p><p>公开的 CodeFlowMu 演示包括任务、报告、复核、ISSUE、生命周期与审计视图 [13]。一个 NL2SQL Worked Case 分离执行与复核：执行者生成报告，复核者检查授权、Schema 使用、只读约束、租户隔离、Join、枚举与结果合理性。该案例展示预期对象链，但不是代表性生产基准。</p><p>由于工程证据早于 C01–C14 标签，综合语料库把选定测试和工件映射到固定标准 Fixture [28]。评估程序为：(1) 锁定产品版本与执行环境；(2) 盘点证据并计算 Hash；(3) 把工件和测试映射到每项标准；(4) 运行选定 Suite 与 Fixture 并保留预期和实际输出；(5) 在不隐藏未满足前置条件的情况下分配产品裁决；(6) 分开报告 Fixture 一致性与产品行为。</p><p>所得证据支持有界结构可行性：持久项目可见协调、角色分离复核、生命周期门禁、Archive 保留与重启相关恢复。它没有证明较低的比较成本、代表性 SME 性能、独立采用、跨部署 Profile 的可移植性或完整 TMPA Core 一致性。</p><h1 id="_6-规范重建契约" tabindex="-1">6. 规范重建契约 <a class="header-anchor" href="#_6-规范重建契约" aria-label="Permalink to &quot;6. 规范重建契约&quot;">​</a></h1><p>TMPA 实现可以把证据保存在不同基底中，但必须暴露足以进行确定性重建的规范文本投影。Reader 接收的是一组<strong>来源候选</strong>，而不是可信的有序日志。它解析并验证候选，保留重复观测，区分同一 ID 下不同内容的冲突，应用 Profile 规则，并输出：</p><ol><li>规范候选集合；</li><li>偏序流程与责任图；</li><li>权威问题集合；</li><li>authoritative、partial、disputed、quarantined 或 rejected 等状态。</li></ol><p>符合规范的重建过程执行以下逻辑步骤：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RECONSTRUCT(source_candidates, profile):</span></span>
<span class="line"><span>  解析并规范化候选</span></span>
<span class="line"><span>  验证 Schema、ID、类型与完整性证据</span></span>
<span class="line"><span>  保留重复观测与冲突候选</span></span>
<span class="line"><span>  按写者流分组有效对象并检查局部序号</span></span>
<span class="line"><span>  从序号、引用、生命周期与 Profile 关系构建边</span></span>
<span class="line"><span>  验证角色权限、职责分离与生命周期合法性</span></span>
<span class="line"><span>  检测缺失引用、禁止环与未解决冲突</span></span>
<span class="line"><span>  推导生命周期、责任、复核与恢复状态</span></span>
<span class="line"><span>  输出规范图和问题集合</span></span></code></pre></div><p>该过程不会静默“修复”无效证据。格式错误对象、非法迁移、缺失引用、同 ID 不同内容或矛盾复核都通过问题集合保持可观察。后续授权解决对象可以改变权威解释，但不会擦除先前证据。</p><h2 id="_6-1-确定性" tabindex="-1">6.1 确定性 <a class="header-anchor" href="#_6-1-确定性" aria-label="Permalink to &quot;6.1 确定性&quot;">​</a></h2><p>令 (S) 为固定最终来源候选集合，(P) 为固定 Profile。当 (S) 的任意枚举或交付排列都产生相同的规范候选集合、图、状态与问题集合时，Reader 具有确定性。</p><p>这是基于集合的要求，而不是声称每个中间视图都完整。在所有证据到达前，Reader 可以报告 partial 或 disputed 状态。一旦可用来源集合相同，输出必须与发现顺序无关。</p><p>证明义务来自四项约束：</p><ul><li>规范化与验证依赖候选内容和 Profile 规则，而不是枚举顺序；</li><li>流内顺序来自显式序号证据；</li><li>跨流顺序来自显式引用与生命周期关系；</li><li>冲突以集合和问题形式保留，而不是使用“最后到达者获胜”。</li></ul><p>本文目前提供证明概要与可执行 Fixture Oracle，而不是机械化证明。C11 Fixture 枚举 24 种排列并获得字节等价 Oracle 输出，但锁定的产品尚未暴露产品级 C11 裁决所要求的完整规范 Graph-and-Issue Serializer。</p><h2 id="_6-2-完整性、身份与真实性" tabindex="-1">6.2 完整性、身份与真实性 <a class="header-anchor" href="#_6-2-完整性、身份与真实性" aria-label="Permalink to &quot;6.2 完整性、身份与真实性&quot;">​</a></h2><p>Digest 与签名证据必须被窄化解释。Digest 可以揭示被覆盖字节是否被修改；经过验证的签名可以在外部信任模型下把字节绑定到密钥。二者都不能证明被签名陈述在事实层面正确。</p><p>恶意、受损或判断错误的参与者可能发布 Schema 有效、生命周期有效、Digest 一致、甚至签名正确，但内容为假的报告。TMPA Core 可以识别并保留该对象，检查其声明权限，并把它与独立复核关联；事实验证需要 Core 之外的工具回执、可复现输出、独立数据源或领域专用验证。</p><p>因此必须分别回答三个问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>所需机制</th></tr></thead><tbody><tr><td>这些字节是否被修改？</td><td>Digest 或防篡改存储</td></tr><tr><td>哪个经过认证的主体签署了它们？</td><td>签名、密钥与身份 Profile</td></tr><tr><td>声明是否为真？</td><td>独立验证或领域证据</td></tr></tbody></table><p>除非部署实际依据对应 Profile 验证了证据，TMPA 不得声称拥有外围身份、策略或密码学系统的保证。</p><h1 id="_7-评估结果" tabindex="-1">7. 评估结果 <a class="header-anchor" href="#_7-评估结果" aria-label="Permalink to &quot;7. 评估结果&quot;">​</a></h1><p>独立维护的 <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a> 是当前 C01–C14 及全部 SHALL/MUST 条款的唯一规范性来源。<a href="/joinwell52/zh/publications/implementation-case-i0.6">Implementation Case Report I0.6</a> 报告当前有边界的 S0.5 工程证据基线；I0.5 仍是不可变的 S0.4 历史基线。本节按研究问题评估结果，不复制规范正文。</p><h2 id="_7-1-按研究问题组织的发现" tabindex="-1">7.1 按研究问题组织的发现 <a class="header-anchor" href="#_7-1-按研究问题组织的发现" aria-label="Permalink to &quot;7.1 按研究问题组织的发现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>研究问题</th><th>发现与证据</th><th>边界</th></tr></thead><tbody><tr><td>RQ1：治理状态充分性</td><td>普通对话与执行界面本身不能保留足够显式的权限、生命周期、冲突与恢复状态，以支持确定性治理重建；支持来自问题诊断、DR1–DR8 以及对象与重建分析</td><td>尚无对比现场实验测量替代架构的失败率</td></tr><tr><td>RQ2：最低架构</td><td>稳定载体、单写者流、显式权限和生命周期、类型化引用、三值判断以及保留来源的确定性重建构成一致的最低契约；支持来自不变量、反例、确定性证明概要与 Core S0.5</td><td>证明尚未机械化；最低性是架构论证，而非普适下界证明</td></tr><tr><td>RQ3：工程可行性与边界</td><td>FCoP、CodeFlowMu 与 WP-13 提供有界证据，表明契约的重要部分可在项目可见基础设施中运行；支持来自参考映射、运行案例与锁定的 I0.6 C01–C14 基线</td><td>2 项 FAIL、3 项未运行、8 项仍为 PARTIAL；独立采用、SME 比较负担与跨 Profile 可移植性尚未建立</td></tr></tbody></table><p>因此，结果对架构一致性和有界实现可行性的支持最强；对组织有效性与生态泛化的支持较弱，后者需要独立与比较证据。</p><h2 id="_7-2-一致性领域摘要" tabindex="-1">7.2 一致性领域摘要 <a class="header-anchor" href="#_7-2-一致性领域摘要" aria-label="Permalink to &quot;7.2 一致性领域摘要&quot;">​</a></h2><p>基线按架构领域汇总；标准的精确定义仍以 Core S0.5 §10.2 为准。</p><table tabindex="0"><thead><tr><th>领域</th><th>标准</th><th>产品级结果</th></tr></thead><tbody><tr><td>对象、不可变性与完整性</td><td>C01、C02、C03、C08</td><td>1 项 FAIL；2 项 PARTIAL；1 项 NOT RUN</td></tr><tr><td>权限与生命周期</td><td>C05、C06、C07</td><td>1 项 FAIL；2 项 PARTIAL</td></tr><tr><td>顺序、引用与冲突</td><td>C04、C09、C10、C12</td><td>3 项 PARTIAL；1 项 NOT RUN</td></tr><tr><td>确定性、恢复与历史</td><td>C11、C13、C14</td><td>1 项 PASS；1 项 PARTIAL；1 项 NOT RUN</td></tr></tbody></table><p>这些是锁定修订上的产品级结果，不是完整 Core、Profile 或 Authenticated Governance Conformance 声明。</p><h2 id="_7-3-s0-5-作者运行产品基线" tabindex="-1">7.3 S0.5 作者运行产品基线 <a class="header-anchor" href="#_7-3-s0-5-作者运行产品基线" aria-label="Permalink to &quot;7.3 S0.5 作者运行产品基线&quot;">​</a></h2><p>I0.6 发布证据包 <code>tmpa-i0.6-local-evidence-20260806-v2</code> [28]。它锁定 FCoP Tag <code>v3.2.5</code> Commit <code>b3dc23439c6aaa6a6b3765655b87e5924e0257f9</code>、基于 Commit <code>c4ebc146cb8ef0409a4c9eb571a8f2432ade3bd0</code> 的隔离 CodeFlowMu 快照，以及 WP-13 V3 包。CodeFlowMu 来源工作树为脏且仅存在本地，因此本轮属于作者本地证据，不是稳定公开复现基线。小典没有固定 S0.5 包，未运行。</p><p>FCoP 记录 1,222 项通过、3 项失败、2 项跳过。CodeFlowMu 记录 Protocol Fixture 8/8、Runtime 1,420 项通过 / 1 项失败 / 1 项跳过、Shell 770/770，Typecheck 全部通过。公开 S0.5 Reference Reader 通过全部 14 项合成 Fixture；这些 PASS 不是产品 PASS。</p><p>产品级裁决为：</p><table tabindex="0"><thead><tr><th>裁决</th><th>标准</th></tr></thead><tbody><tr><td>PASS</td><td>C14</td></tr><tr><td>PARTIAL</td><td>C01、C03、C04、C05、C06、C09、C10、C13</td></tr><tr><td>NOT RUN</td><td>C08、C11、C12</td></tr><tr><td>FAIL</td><td>C02、C07</td></tr></tbody></table><p>C02 失败记录 FCoP <code>parent</code> 持久化/读回与 Release Surface 未闭合。C07 失败记录 CodeFlowMu 提示语契约不一致——可读输出 <code>需 ADMIN/PM 人工裁定</code> 没有命中测试要求——不是编码损坏。两项失败均须在对应修复和全量复测前保留。</p><h2 id="_7-4-解释-产品投影缺口" tabindex="-1">7.4 解释：产品投影缺口 <a class="header-anchor" href="#_7-4-解释-产品投影缺口" aria-label="Permalink to &quot;7.4 解释：产品投影缺口&quot;">​</a></h2><p>8 项 PARTIAL 共享一个主要实现缺口。通用 S0.5 只读 Reference Reader 已存在，而 FCoP 与 CodeFlowMu 尚未暴露受维护的投影适配器，把各自原生证据规范化为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>来源候选</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>规范候选集合</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>流程与责任图</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>权威问题集合</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>authoritative / partial / disputed / quarantined 视图</span></span></code></pre></div><p>产品投影将直接改善 C03、C05、C09 和 C13，并为 C04、C06、C10 提供基础设施；它还将建立 C11–C12 所需的产品执行路径。C01 仍存在 Schema 覆盖缺口；C02 与 C07 需要针对已保留失败进行修复；C08 需要被覆盖内容的 Digest 证据。</p><p>语料库与基线由作者产生。语料库现已公开，但任何独立验证声明仍必须先有独立重跑。</p><h1 id="_8-讨论、局限与效度威胁" tabindex="-1">8. 讨论、局限与效度威胁 <a class="header-anchor" href="#_8-讨论、局限与效度威胁" aria-label="Permalink to &quot;8. 讨论、局限与效度威胁&quot;">​</a></h1><p>TMPA 的贡献是流程治理契约，而不是完整企业 Agent 平台。它在发布时显式化工作身份、责任、复核、生命周期、冲突与恢复，并从持久证据中重建这些关系。FCoP 证明一个有用子集可以在普通项目环境中运行，而不强制要求 Broker 或协调数据库。</p><p>该架构不替代：</p><ul><li>企业 IAM、凭证签发或密钥管理；</li><li>Runtime Gateway、Policy Engine 或 Admission Control；</li><li>模型评估与事实验证；</li><li>OTel、SIEM、CMDB、GRC 或企业 Agent 资产清单；</li><li>数据库事务、分布式共识或拜占庭容错；</li><li>法律合规计划。</li></ul><p>这些系统可以向 TMPA 提供 ID、策略决策、执行回执与受保护存储。除非经过验证并引用，其保证仍属于外部系统。</p><h2 id="_8-1-证据成熟度" tabindex="-1">8.1 证据成熟度 <a class="header-anchor" href="#_8-1-证据成熟度" aria-label="Permalink to &quot;8.1 证据成熟度&quot;">​</a></h2><p>本文区分四个声明层级：</p><ol><li><strong>specified：</strong> 已发布规则、Schema 或标准；</li><li><strong>implemented：</strong> 代码执行该规则；</li><li><strong>demonstrated：</strong> 运行案例展现该行为；</li><li><strong>independently adopted：</strong> 外部系统依赖并验证该行为。</li></ol><p>架构和标准已规定；FCoP 提供实现证据；CodeFlowMu 与小典 AI 提供边界明确的演示证据；独立采用尚未成立。</p><p>论文作者同时是被评估系统的发起者和主要开发者。这使详细工件可被访问，但也产生自我评估与选择偏差风险。因此，语料库分别标注作者生成证据、非门禁现场证据、仅 Fixture Oracle 结果和产品级裁决。</p><h2 id="_8-2-sme-first-声明" tabindex="-1">8.2 SME-first 声明 <a class="header-anchor" href="#_8-2-sme-first-声明" aria-label="Permalink to &quot;8.2 SME-first 声明&quot;">​</a></h2><p>“SME-first”是运行范围，不表示所有中小企业需求相同，也不表示 TMPA 不适合大型组织。轻量 Profile 假设平台与运维能力有限。大型部署可以通过数据库、对象存储、身份系统、复制和企业控制平面保留同样语义。</p><p>决定性的实证问题仍然是：收益是否足以抵偿纪律和资源成本。所需测量包括：</p><table tabindex="0"><thead><tr><th>实验</th><th>所需证据</th></tr></thead><tbody><tr><td>部署负担</td><td>依赖、安装步骤、设置时间、建立第一支团队的时间、备份与迁移</td></tr><tr><td>重建</td><td>延迟与乱序流、中间 partial 状态、字节等价最终输出</td></tr><tr><td>故障与恢复</td><td>重复、非法迁移、缺失引用、篡改、重启与恢复时间</td></tr><tr><td>人类可检查性</td><td>识别所有权、缺失证据、复核状态与下一责任人的能力</td></tr><tr><td>采纳纪律</td><td>Onboarding、绕过、更正、回退聊天、感知负担与持续使用</td></tr><tr><td>代表性负载</td><td>延迟、CPU、内存、存储增长、冲突率与恢复时间</td></tr></tbody></table><p>当前语料库提供规范化基线，但没有完成这些测量。</p><h2 id="_8-3-数字员工-profile-与隐私" tabindex="-1">8.3 数字员工 Profile 与隐私 <a class="header-anchor" href="#_8-3-数字员工-profile-与隐私" aria-label="Permalink to &quot;8.3 数字员工 Profile 与隐私&quot;">​</a></h2><p><strong>数字员工</strong>一词仅作为持久 AI 工作角色的工程标签。它不主张雇佣身份、法律人格、意识、人类意图、自主组织权威，也不意味着替代承担责任的人类或组织。</p><p>未来 Profile 可以定义岗位范围、接受委托、交接、暂停、重新分配与退役。这些是应用语义，不改变 Core。</p><p>文本治理提高可检查性，但可能暴露敏感信息。部署应最小化内容，把秘密与治理元数据分离，应用访问控制与加密，并定义保留和删除程序。治理历史不可变不等于敏感 Payload 必须公开可读。</p><h2 id="_8-4-效度威胁" tabindex="-1">8.4 效度威胁 <a class="header-anchor" href="#_8-4-效度威胁" aria-label="Permalink to &quot;8.4 效度威胁&quot;">​</a></h2><p><strong>构念效度。</strong> C01–C14 操作化治理结构与重建行为，但不直接测量事实真实性、人类可用性、生产率或组织问责。标准通过不得被解释为这些外部构念上的成功。</p><p><strong>内部效度。</strong> 作者选择了架构、系统、案例与证据映射，并运行了基线。版本差异以及从历史工件到后设标准的回溯映射都可能影响结果。固定修订、Hash、显式前置条件以及分离产品与 Fixture 裁决可以降低但不能消除该风险。</p><p><strong>外部效度。</strong> 主要实现是文件型 Profile，案例集合较小，且大量观测执行发生在项目局部环境。结果未必能原样迁移到数据库型、高度分布式、受监管、对抗性或高吞吐部署。</p><p><strong>结论效度。</strong> 裁决计数只是选定路径的描述性结果，不是统计估计、完整一致性证据，也不是与聊天、Event Log、Workflow Engine 或数据库替代方案的因果比较。</p><p><strong>可复现性。</strong> 当前语料库由作者生成。它现已具备稳定公开仓库路径、可执行复现命令、环境声明与 SHA-256 Manifest；仍需要独立重跑。</p><h2 id="_8-5-局限与可证伪条件" tabindex="-1">8.5 局限与可证伪条件 <a class="header-anchor" href="#_8-5-局限与可证伪条件" aria-label="Permalink to &quot;8.5 局限与可证伪条件&quot;">​</a></h2><p>TMPA 的核心声明必须保持可被反证：</p><table tabindex="0"><thead><tr><th>声明</th><th>会削弱或推翻该声明的证据</th></tr></thead><tbody><tr><td>相同来源集合允许确定性重建</td><td>符合规范的 Reader 在相同 Profile 与来源集合上产生不同规范图或问题输出</td></tr><tr><td>持久文本证据改善责任恢复</td><td>受控恢复任务不优于相关替代方案，或无法可靠识别责任与缺失证据</td></tr><tr><td>架构能以最低基础设施运行</td><td>正确性依赖未声明的协调数据库、Broker、全局时钟或集中可变日志</td></tr><tr><td>SME-first Profile 在运行上可行</td><td>在代表性 SME 使用中，部署、维护、存储或人员纪律成本超过测得的治理收益</td></tr><tr><td>语义可跨 Profile 移植</td><td>独立实现在不同存储基底之间无法保留对象、权限、生命周期、冲突与重建语义</td></tr></tbody></table><h2 id="_8-6-出版与可复现边界" tabindex="-1">8.6 出版与可复现边界 <a class="header-anchor" href="#_8-6-出版与可复现边界" aria-label="Permalink to &quot;8.6 出版与可复现边界&quot;">​</a></h2><p>A0.5 是理论架构论文；Core S0.5 是当前规范性来源；Implementation Case I0.6 报告当前作者运行的 S0.5 工程证据基线，I0.5 保留 S0.4 历史。论文可以总结配套工件，但不得静默重定义其含义，也不得把 Reference Reader Fixture 提升为产品一致性。</p><p>对外投稿前，语料库仍需要可取回的 CodeFlowMu 锁定源码或复现包，以及至少一次独立重跑。低资源部署测量仍是 SME 可行性声明的独立发布要求。</p><h1 id="_9-结论" tabindex="-1">9. 结论 <a class="header-anchor" href="#_9-结论" aria-label="Permalink to &quot;9. 结论&quot;">​</a></h1><p>TMPA 是一种<strong>面向中小企业、最低基础设施条件的文本消息多智能体异步流程架构</strong>。文本承载持久工作与状态；每项工作有一个稳定主载体；每个已发布对象有一个写者并属于一条局部串行流；各条独立流异步推进；聚合与确定性读取重建偏序流程、责任、生命周期、冲突、恢复和审计视图。</p><p>该架构沿着<strong>实践 → 方法 → 理论</strong>形成：小典 AI 暴露多角色协调问题，原始 TMPA 识别文本异步方法，FCoP 抽取并成熟其可复用文件协调与复核子集，CodeFlowMu 提供下游应用反馈，本文则形式化对象、不变量、保证边界和一致性标准。早期 Pipeline 证明起源，而不是追溯性的 Core Conformance。</p><p>A0.5 在架构层回答 RQ1 与 RQ2，并为 RQ3 提供由作者运行、版本锁定的基线。在 I0.6/S0.5 评估下，<strong>产品级 1 项 PASS、8 项 PARTIAL、3 项 NOT RUN、2 项 FAIL</strong>。FCoP v3.2.5 记录 1,222 项通过、3 项失败、2 项跳过；隔离 CodeFlowMu 快照记录 Runtime 1,420 项通过、1 项失败、1 项跳过，以及 Shell 770/770。独立 S0.5 Reference Reader 通过全部 14 项合成 Fixture，但这不替代产品执行、干净公开复现或独立验证。</p><p>决定性剩余问题是 RQ3：组织能否在普通项目环境中，以可接受的资源与纪律成本持续获得 TMPA 的责任、复核、恢复与证据收益。该声明仍需要产品投影适配器、可取回的 CodeFlowMu 复现包、低资源部署与恢复测量、基线对比、代表性使用和独立复现。TMPA 自身也不确立认证身份、强隔离、受保护存储、拜占庭容错、参与者声明的事实真实性或生态采用。</p><hr><h1 id="工件可用性" tabindex="-1">工件可用性 <a class="header-anchor" href="#工件可用性" aria-label="Permalink to &quot;工件可用性&quot;">​</a></h1>`,147)])])}const P=e(r,[["render",i]]);export{u as __pageData,P as default};
